import { useEffect, useRef, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { io } from "socket.io-client";
import api from "../api";

const socket = io("http://localhost:5000");

function Chat() {
  const userId = Number(localStorage.getItem("userId"));
  const [searchParams] = useSearchParams();

  const initialUser = searchParams.get("user")
    ? Number(searchParams.get("user"))
    : null;

  const [messages, setMessages] = useState([]);
  const [contacts, setContacts] = useState([]);
  const [activeUser, setActiveUser] = useState(initialUser);
  const [text, setText] = useState("");

  const messagesRef = useRef([]);

  /* ===== JOIN SOCKET ===== */
  useEffect(() => {
    if (!userId) return;
    socket.emit("join", userId);
  }, [userId]);

  /* ===== RECEIVE MESSAGE ===== */
  useEffect(() => {
    socket.on("receive_message", (data) => {
      setMessages((prev) => [...prev, data]);

      const other =
        data.sender_id === userId
          ? data.receiver_id
          : data.sender_id;

      if (!contacts.includes(other)) {
        setContacts((prev) => [...prev, other]);
      }
    });

    return () => socket.off("receive_message");
  }, [contacts, userId]);

  /* ===== FETCH CONVERSATION ===== */
  useEffect(() => {
    if (!userId || !activeUser) return;

    api
      .get("/chat/conversation", {
        params: {
          user1: userId,
          user2: activeUser,
        },
      })
      .then((res) => {
        setMessages(res.data || []);
        messagesRef.current = res.data || [];
      });
  }, [userId, activeUser]);

  /* ===== SEND MESSAGE ===== */
  const sendMessage = () => {
    if (!text.trim() || !activeUser) return;

    const payload = {
      sender_id: userId,
      receiver_id: activeUser,
      batch_id: null,
      message_text: text,
    };

    api.post("/chat", payload);

    socket.emit("send_message", payload);

    setMessages((prev) => [...prev, payload]);
    setText("");

    if (!contacts.includes(activeUser)) {
      setContacts((prev) => [...prev, activeUser]);
    }
  };

  return (
    <div className="chat-layout">
      <aside className="chat-sidebar">
        <h3>Chats</h3>
        {contacts.map((id) => (
          <div
            key={id}
            className={activeUser === id ? "active" : ""}
            onClick={() => setActiveUser(id)}
          >
            User {id}
          </div>
        ))}
      </aside>

      <main className="chat-main">
        {!activeUser ? (
          <p>Select a chat</p>
        ) : (
          <>
            <div className="chat-header">
              Chat with User {activeUser}
            </div>

            <div className="chat-messages">
              {messages.map((m, i) => (
                <div
                  key={i}
                  className={
                    m.sender_id === userId ? "sent" : "received"
                  }
                >
                  {m.message_text}
                </div>
              ))}
            </div>

            <div className="chat-input">
              <input
                value={text}
                onChange={(e) => setText(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && sendMessage()}
                placeholder="Type..."
              />
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        )}
      </main>
    </div>
  );
}

export default Chat;
